In this paper we consider convex conic programming in the form of
\begin{equation}\label{eq:conic-cp}
\begin{array}{rl}
F^*=\min & \left\{F(x) := f(x) + P(x)\right\} \\
\mbox{s.t.} &  g(x)\preceq_\mcK 0,
\end{array}
\end{equation}
where $f, P:\Re^n\rightarrow(-\infty,\infty]$ are proper closed convex functions, $\mcK$ is a closed convex cone in $\Re^m$, the symbol $\preceq_\mcK$ denotes the partial order induced by $\mcK$, that is, $y\preceq_\mcK z$ if and only if $z-y\in\mcK$, and the mapping $g:\Re^n\rightarrow\Re^m$ is convex with respect to $\mcK$, that is,
\begin{equation}
\label{eq:conic-cvx}
g(\alpha x + (1-\alpha)y) \preceq_\mcK \alpha g(x) + (1-\alpha)g(y), \quad\forall x,y\in\Re^n, \; \alpha\in[0,1].
\end{equation}
The associated Lagrangian dual problem of \eqref{eq:conic-cp} is given by 
\beq \label{dual-prob}
d^*=\sup\limits_{\lambda\in\mcK^{*}} \inf\limits_x\  \{ f(x) + P(x) + \Inner{\lambda}{g(x)}\},
\eeq
where $\mcK^*$ is the dual cone of $\mcK$ (see Section \ref{sec:preliminaries}). 


\begin{ass}
	\label{ass:function}
	\begin{itemize}
		\item[(a)] The proximal operator associated with $P$ can be exactly evaluated, and the domain of $P$, denoted by $\dom(P)$, is compact.\footnote{Some problems with unbounded $\dom(P)$ can be reformulated as the ones satisfying this assumption. For example, when $f$ is bounded below and $P$ is coercive, the problem generally can be reformulated as the one with the objective $f+\tilde P$ for some $\tilde P$ with a compact domain. Such a problem often arises in sparse or low-rank learning, in which $f$ is typically a nonnegative loss function and $P$ is the $\ell_1$- or nuclear-norm.}
		\item[(b)] The projection onto $\mcK$ can be exactly evaluated.
		\item[(c)] The functions $f$ and $g$ are continuously differentiable on an open set $\Omega$ containing $\dom(P)$,  and $\nabla f$ and $\nabla g$  are Lipschitz continuous on $\Omega$ with Lipschitz constants $L_{\nabla f}$ and $L_{\nabla g}$, respectively.\footnote{The symbol $\nabla g$ denotes the transpose of the Jacobian of $g$.}
\item[(d)] The strong duality holds for problems \eqref{eq:conic-cp} and \eqref{dual-prob}, that is, both problems have optimal solutions and moreover their optimal values $F^*$ and $d^*$ are equal. 
	\end{itemize}
\end{ass}

\begin{equation}
\label{eq:eps-approx-kkt-point}
\dist(0, \nabla f(x) + \partial P(x) + \nabla g(x)\lambda) \leq \epsilon, \quad \dist(g(x), \mcN_{\mcK^*}(\lambda))\leq \epsilon, \quad (x,\lambda) \in \dom(P) \times \mcK^*
\end{equation}

The following notations will be used throughout this paper. Let $\Re^n$ denote the Euclidean space of dimension $n$, $\langle\cdot,\cdot\rangle$ denote the standard inner product, and $\|\cdot\|$ stand for the Euclidean norm. The symbols $\Re_+$ and $\Re_{++}$ stand for the set of nonnegative and positive real numbers, respectively.  

Given a closed convex function $h:\Re^n\rightarrow(-\infty,\infty]$, $\partial h$ and $\dom (h)$ denote the subdifferential and domain  of $h$, respectively.  The proximal operator associated with $h$ is denoted by  
$\prox_h$,  that is,
\begin{equation*}
\label{eq:def-prox}
\prox_h(z) = \argmin_{x\in\Re^n} \left\{ \frac{1}{2}\|x - z\|^2 + h(x) \right\}, \quad \forall z \in \Re^n.
\end{equation*}
Given a non-empty closed convex set $C\subseteq\Re^n$, $\dist(z,C)$ stands for the Euclidean distance from $z$ to $C$, and $\Pi_C(z)$ denotes the Euclidean projection of $z$ onto $C$, namely, 
\[
 \Pi_C(z) = \argmin\{\|z - x\|: x\in C\}, \quad \dist(z,C)=\left\|z - \Pi_C(z)\right\|, \quad \forall z \in \Re^n.
\]
The normal cone of $C$ at any $z\in C$ is denoted by $\mcN_C(z)$. For the closed convex cone $\mcK$, we use $\mcK^*$ to denote the dual cone of $\mcK$, that is,  $\mcK^* = \{y\in\Re^m: \langle y,x\rangle\geq 0, \; \forall x\in\mcK\}$.

The Lagrangian function $l(x,\lambda)$ of problem~\eqref{eq:conic-cp} is defined as
\begin{equation*}
l(x,\lambda) = \left\{
\begin{array}{ll}
f(x) + P(x) + \Inner{\lambda}{g(x)} & \mbox{if}\; x\in \dom(P) \mbox{ and } \lambda \in \mcK^{*}, \\
-\infty & \mbox{if}\; x\in \dom(P) \mbox{ and } \lambda\notin\mcK^{*}, \\
\infty & \mbox{if}\; x\notin \dom(P),
\end{array}
\right.
\end{equation*}
which is a closed convex-concave function. The Lagrangian dual function $d:\Re^m\rightarrow[-\infty,\infty)$ is defined as 
\begin{equation}
\label{eq:lag-dual-func}
d(\lambda) = \inf_x l(x,\lambda) = \left\{
\begin{array}{ll}
\inf\limits_x\  \{ f(x) + P(x) + \Inner{\lambda}{g(x)}\} & \mbox{if}\; \lambda\in\mcK^{*},\\
-\infty & \mbox{if}\; \lambda\notin\mcK^{*},
\end{array}
\right.
\end{equation}
which is a closed concave function. Moreover, the augmented Lagrangian function for problem~\eqref{eq:conic-cp} is defined as (e.g., see~\cite{Shapiro04})
\begin{equation}
\label{eq:al-func}
\mcL(x,\lambda;\rho) = f(x) + P(x) + \frac{1}{2\rho}\Big[\dist^2\big(\lambda + \rho g(x), -\mcK\big) - \|\lambda\|^2\Big],
\end{equation}
where $\rho>0$ is  a penalty parameter. For convenience, we let
\beq \label{S-fun}
\mcS(x,\lambda;\rho):= f(x) + \frac{1}{2\rho} \dist^2\big(\lambda+\rho g(x), -\mcK \big).
\eeq
It is clear to see that 
\[
\mcL(x,\lambda;\rho) = \mcS(x,\lambda;\rho) + P(x) - \frac{\|\lambda\|^2}{2\rho}.
\]
The augmented Lagrangian dual function of~\eqref{eq:conic-cp} is given by
\begin{equation}
\label{eq:aug-dual-func}
d(\lambda;\rho)= \min_{x\in\Re^n} \mcL(x,\lambda;\rho).
\end{equation}
The Lagrangian dual problem \eqref{dual-prob} can thus be rewritten as  
\begin{equation}\label{eq:dual-conic-cp}
d^{*} = \max_\lambda\; d(\lambda).
\end{equation}
Let $\partial l:\Re^n\times\Re^m\rightrightarrows\Re^n\times \Re^m$ and $\partial d:\Re^m\rightrightarrows\Re^m$ be respectively the subdifferential mappings associated with $l$ and $d$ (e.g., see \cite{R97}). We define two set-valued operators associated with problems \eqref{eq:conic-cp} and \eqref{dual-prob} as follows:
\beqa
&&\mcT_d: \lambda \rightarrow \{ u\in\Re^m: -u\in \partial d(\lambda)\},  \quad \forall \lambda\in\Re^m, \label{eq:def-two-opt1} \\
&& \mcT_l: (x,\lambda) \rightarrow \{ (v,u)\in\Re^n\times\Re^m: (v,-u)\in\partial l(x,\lambda)\}, \quad \forall (x,\lambda) \in \Re^n \times \Re^m. \label{eq:def-two-opt2}
\eeqa
It is well known that $\lambda^*$ is an optimal solution of the Lagrangian dual problem~\eqref{eq:dual-conic-cp} if and only if $0\in \partial d(\lambda^*)$, and $(x^*,\lambda^*)$ is a saddle point\footnote{$(x^*,\lambda^*)$ is called a saddle point of $l$ if it satisfies $ \sup_{\lambda}l(x^*,\lambda) = l(x^*,\lambda^*) = \inf_x l(x,\lambda^*)$.} of $l$ if and only if $(0,0)\in\partial l(x^*,\lambda^*)$. In addition, it can be verified that 
\begin{equation}
\label{eq:express-Tl}
\partial l(x,\lambda) = \left\{
\begin{array}{ll}
\left(
\begin{array}{c}
\nabla f(x) + \partial P(x) + \nabla g(x)\lambda \\
g(x) - \mcN_{\mcK^*}(\lambda)
\end{array}
\right), & \mbox{if}\; x\in\dom(P)\; \mbox{and}\; \lambda\in\mcK^*, \medskip
\\ 
\emptyset, & \mbox{otherwise}.
\end{array}\right.
\end{equation}


\begin{defi}
	\label{defi:approx-KKT}
	Given any $\epsilon>0$, we say $(x,\lambda)\in\Re^n\times\Re^m$ is an $\epsilon$-KKT solution of~\eqref{eq:conic-cp}  if there exists $(u,v)\in\partial l(x,\lambda)$ such that $\|u\|\leq \epsilon$ and $\|v\|\leq \epsilon$.
\end{defi}

We next present the subroutine Postprocessing that is used in Step 4 of Algorithm \ref{alg:i-al}. Before proceeding, let $L_g$ be the  Lipschitz constant of $g$ on $\dom(P)$ and $M_g = \max\limits_{x\in\dom(P)}\|g(x)\|$.  


In the rest of this section we present our main results for Algorithm \ref{alg:i-al}, whose proof is deferred  to Subsection \ref{sec:pf-i-al}. To proceed, we introduce some further notation below. Let $\Lambda^*$ be the set of optimal solutions of problem \eqref{dual-prob} and $\hat\lambda^*\in \Lambda^*$ such that $\|\lambda^0-\hat\lambda^*\|=\dist(\lambda^0,\Lambda^*)$. In addition, we define 
\begin{align}
 & D_X = \max\limits_{x,y\in\dom(P)}\|x - y\|,  \  D_\Lambda = \|\lambda^0 - \hat\lambda^*\|, \ B = L_{\nabla f} + L_{\nabla g}(\|\hat\lambda^*\| + D_\Lambda), \label{param} \\
 & C = L_{\nabla g}M_g + L_g^2, \ \bD=\max\{D_\Lambda,1\}, \ \bB =\max\{B,1\}, \ \bC =\max\{C,1\}, \label{bparam}
\end{align}
where  $L_{\nabla f}$, $L_{\nabla g}$, $L_g$ and $M_g$ are defined above.


\begin{algo}[An adaptively regularized I-AL method]
	\label{alg:mi-al}
	\normalfont
	\mbox{}
	\begin{itemize}
		\item[0.] Input $\epsilon>0$, $(x^0,\lambda^0)\in\dom(P)\times \mcK^*$,  nondecreasing $\{\rho_k\} \subset \Re_{++}$, and $0<\eta_k \downarrow 0$. Set $k=0$.
		\item[1.] Apply Algorithm~\ref{alg:opt-fom-str} (in Appendix \ref{app-fom}) to the problem $\min_x \varphi_k(x)$ to  find $x^{k+1}\in\dom(P)$ satisfying
		\begin{equation}
		\label{eq:inext-subprob-m}
		\dist (0, \partial \varphi_k(x^{k+1})) \leq \eta_k,\footnote{In view of Proposition \ref{prop:cplx-fom-str-cvx},  one can terminate Algorithm~\ref{alg:opt-fom-str} once a point $x^{k+1}$ satisfying $2L_{\nabla \phi}\|\tilde{x}^{k+1} - x^{k+1}\| \le \eta_k$ is found, where $\phi(\cdot)= \varphi_k(\cdot)-P(\cdot)$, $\tilde{x}^{k+1}= \prox_{P/L_{\nabla \phi}}\left( x^{k+1} - \nabla \phi(x^{k+1})/L_{\nabla \phi} \right)$, and $L_{\nabla \phi}$ is the Lipschitz constant of $\nabla \phi$. Such $x^{k+1}$ clearly satisfies \eqref{eq:inext-subprob-m}.}
		\end{equation}
		where 
		\begin{equation}
		\label{eq:prox-al-func}
		\varphi_k(x) = \mcL(x,\lambda^k;\rho_k) + \frac{1}{2\rho_k}\|x - x^k\|^2.
		\end{equation}
		\item[2.] Set $\lambda^{k+1} = \Pi_{\mcK^*}\big(\lambda^k + \rho_k g(x^{k+1}) \big)$. 
		\item[3.] If $(x^{k+1},\lambda^{k+1})$ satisfies \eqref{eq:eps-approx-kkt-point} or the following two inequalities are satisfied
		\begin{equation}
		\label{eq:check-stop-m}
		\frac{1}{\rho_k}\|(x^{k+1}, \lambda^{k+1}) - (x^k,\lambda^k)\| \leq \frac{\epsilon}{2}, \quad \eta_k \leq \frac{\epsilon}{2},
		\end{equation}
		output $(x^+, \lambda^{+}) = (x^{k+1}, \lambda^{k+1})$ and terminate the algorithm.
		\item[4.] Set $k \leftarrow k+1$ and go to Step 1.
	\end{itemize}
	{\bf End.}
\end{algo}

For ease of later reference, we refer to the iterations of Algorithm~\ref{alg:opt-fom-str} for solving the 
AL subproblems as the {\it inner iterations} of Algorithm \ref{alg:mi-al}, and call the update from 
$(x^k,\lambda^k)$ to $(x^{k+1},\lambda^{k+1})$ an {\it outer iteration} of Algorithm \ref{alg:mi-al}. 
Notice from \eqref{eq:prox-al-func} that $\varphi_k$ is strongly convex with modulus $1/\rho_k$. The AL subproblem $\min_x \varphi_k(x)$ arising in Algorithm \ref{alg:mi-al} can thus be suitably solved by Algorithm~\ref{alg:opt-fom-str}.


In the rest of this section, we present our main results for Algorithm \ref{alg:mi-al}, whose proof is deferred  to Subsection \ref{sec:pf-mi-al}. Before proceeding, we introduce some further notation that will be used subsequently. Let $X^*$ be the set of optimal solutions of problem \eqref{eq:conic-cp} and $\hat x^*\in X^*$ such that 
$\|x^0-\hat x^*\|=\dist(x^0,X^*)$. In addition, we define 
\beq \label{param-m} 
{\bar D}_X =\max\{D_X,1\}, \ D=  \dist(x^0,X^*)+D_\Lambda, \ \bar{D}= \max\{D,1\}, \ \hat B = L_{\nabla f} + L_{\nabla g}\|\hat\lambda^*\| + L_{\nabla g}D, 
\eeq

