\begin{thm}
	\label{prop:output-gantee-m}
	\bi
	\item[(i)]
	If  Algorithm~\ref{alg:mi-al} successfully terminates, then the output $(x^+,\lambda^+)$  is an $\epsilon$-KKT solution of problem \eqref{eq:conic-cp}.
	\item[(ii)]
	Suppose that $\{\rho_k\}$  and $\{\eta_k\}$ satisfy that
	\beq \label{rho-eta-m}
	\rho_k>0 \ \mbox{is nondecreasing}, \quad 0<\eta_k \downarrow 0, \quad 
	\frac{\sum_{i=0}^{2k}\rho_i\eta_i}{\rho_k\sqrt{k+1}} \to 0.  \footnote{For example,  $\rho_k = \rho_0\alpha^k$ and $\eta_k = \eta_0\beta^k$ satisfy \eqref{rho-eta-m} for any $\rho_0>0$, $\eta_0>0$, $\alpha>1$ and $0<\beta<1/\alpha$.}
	\eeq 
	Then Algorithm~\ref{alg:mi-al} terminates in a finite number of outer iterations. 
	\item[(iii)] Furthermore, if $N$ is a nonnegative integer such that
	\begin{equation}
	\label{eq:cplx-out-general-m}
	\frac{D + \sum_{k=0}^N \rho_k\eta_k}{\rho_N} \leq \frac{\epsilon}{2}, \quad \eta_N \leq \frac{\epsilon}{2},
	\end{equation}
	then Algorithm~\ref{alg:mi-al} terminates in at most $N+1$ outer iterations.
	\ei
\end{thm}

