\begin{prop}
Under Assumption~\ref{ass:function}, $x^*\in\Re^n$ is an optimal solution of~\eqref{eq:conic-cp} if and only if there exists $\lambda^*\in\Re^m$ such that
\begin{equation}
\label{eq:KKT-condition}
(0,0)\in \partial l(x^*,\lambda^*),
\end{equation}
or equivalently, $(x^*,\lambda^*)$ satisfies the KKT conditions for~\eqref{eq:conic-cp}, that is,
\[
0\in\nabla f(x^*) + \partial P(x^*) + \nabla g(x^*) \lambda^*, \quad \lambda^* \in\mcK^*, \quad g(x^*)\preceq_\mcK 0, \quad \langle \lambda^*, g(x^*) \rangle = 0.
\]
\end{prop}

\begin{proof}
The result \eqref{eq:KKT-condition} follows from \cite[Theorem 36.6]{R97}. By \eqref{eq:express-Tl}, it is not hard to see that \eqref{eq:KKT-condition} holds if and only if $0\in \nabla f(x^*) + \partial P(x^*) + \nabla g(x^*)\lambda^*$, $\lambda^*\in\mcK^*$, and $g(x^*) \in\mcN_{\mcK^*}(\lambda^*)$. By the definition of $\mcK^*$ and $\mcN_{\mcK^*}$, one can verify that $g(x^*)\in\mcN_{\mcK^*}(\lambda^*)$ is equivalent to $g(x^*)\preceq_\mcK 0$ and $\langle\lambda^*, g(x^*) \rangle = 0$. The proof is then completed.
\end{proof}

\begin{lemma}
	\label{lemma:al-func-elp}
	For any $(x,\lambda,\rho)\in\Re^n\times\Re^m\times\Re_{++}$, the following identity holds
	\begin{equation*}
	\mcL(x,\lambda;\rho) = \max_{\eta\in\Re^m} \left\{ l(x,\eta) - \frac{1}{2\rho}\|\eta - \lambda\|^2\right\}.
	\end{equation*}
	In addition, if $x\in\dom(P)$, the maximum is attained uniquely at $\bar{\lambda} = \Pi_{\mcK^*}(\lambda + \rho g(x))$. Consequently, the following statements hold.
	\begin{itemize}
		\item[(i)] For any $(\lambda,\rho)\in\Re^m\times\Re_{++}$, $d(\lambda;\rho)$ satisfies that
		\begin{equation}
		\label{eq:al-dual-func-elp-cp}
		d(\lambda;\rho) = \max_{\eta\in\Re^m}\left\{ d(\eta) - \frac{1}{2\rho}\|\eta - \lambda\|^2\right\}. 
		\end{equation}
		\item[(ii)] $\mcL(x,\lambda;\rho)$ is a convex function in $x$, and for any $x\in\dom(P)$, we have
\[
		\partial_x\mcL(x,\lambda;\rho) = \partial_x l(x,\bar{\lambda}).
\]
		\item[(iii)] $\mcL(x,\lambda;\rho)$ is a concave function in $\lambda$, and for any $x\in\dom(P)$, it is differentiable in $\lambda$ and
\[
		\frac{1}{\rho}(\bar{\lambda} - \lambda) = \nabla_\lambda \mcL(x,\lambda;\rho) \in \partial_\lambda l(x,\bar{\lambda}).
\]
	\end{itemize}
\end{lemma}

\begin{lemma}
\label{lemma:cplx-ippa} 
Let $\mcT:\Re^n\rightrightarrows\Re^n$ be a maximally monotone operator and  $z^*\in\Re^n$  such that $0\in\mcT(z^*)$. Let $\{z^k\}$ be a sequence generated by an inexact PPA, starting with some $z^0$ and obtaining $z^{k+1}$ by approximately evaluating $\mcJ_{\rho_k}(z^k)$ such that 
\begin{equation}
\label{eq:iter-PPA}
\|z^{k+1} - \mcJ_{\rho_k}(z^k)\| \le  e_k
\end{equation}
for some $\rho_k>0$ and $e_k\geq 0$, where $\mcJ_\rho=(\mcI + \rho\mcT)^{-1}$  and $\mcI$ is the identify operator. Then we have
\beqa
\|z^s - z^{*}\| \leq \|z^t - z^{*}\| + \sum_{i=t}^{s-1}e_i, \quad \forall s\geq t\geq 0, \label{eq:iter-ppa-bd} \\
\|z^{k+1} - z^k\| \leq \|z^0 - z^*\| + \sum_{i=0}^k e_i, \quad \forall k\geq 0. \label{eq:ippa-iter-cplx}
\eeqa
Moreover, for any $K\ge 1$, we have
\begin{equation}
\label{eq:ippa-iter-cplx-min}
\min_{K\leq k\leq 2K}\|z^{k+1} - z^k\| \leq \frac{\sqrt{2}\left(\|z^0 - z^{*}\| + 2\sum_{k=0}^{2K}e_k\right)}{\sqrt{K+1}}.
\end{equation}
\end{lemma}

\begin{lemma}
\label{lemma:mi-al=i-ppa}
Let $\{(x^k,\lambda^k)\}$ be generated by Algorithm~\ref{alg:mi-al}. For any $k\geq 0$, one has
\begin{equation}
\label{eq:mi-al=i-ppa}
\|(x^{k+1},\lambda^{k+1}) - \mcJ_{\rho_k}(x^k,\lambda^k)\| \leq \rho_k\eta_k,
\end{equation}
where $\mcJ_{\rho_k}=(\mcI + \rho_k\mcT_l)^{-1}$ and $\mcT_l$ is defined in \eqref{eq:def-two-opt2}.
\end{lemma}

\begin{proof}
By Lemma~\ref{lemma:al-func-elp} and $\lambda^{k+1} = \Pi_{\mcK^*}\big(\lambda^k + \rho_k g(x^{k+1})\big)$, one has
\begin{equation}
\label{eq:diff-x-lambda-m}
\partial_x \mcL(x^{k+1},\lambda^k;\rho_k) = \partial_x l(x^{k+1},\lambda^{k+1}), \quad \frac{1}{\rho_k}(\lambda^{k+1} - \lambda^k) \in \partial_\lambda l (x^{k+1},\lambda^{k+1}).
\end{equation}
By~\eqref{eq:inext-subprob-m}, there exists $\|v\|\leq \eta_k$ such that
$$ v \in \partial_x \mcL(x^{k+1},\lambda^k;\rho_k) + \frac{1}{\rho_k}(x^{k+1} - x^k). $$
This together with~\eqref{eq:diff-x-lambda-m} implies that
\begin{equation}
\label{eq:diff-x-lambda-m-v}
x^k + \rho_kv \in \rho_k \partial_x l(x^{k+1},\lambda^{k+1}) +  x^{k+1}, \quad \lambda^k \in -\rho_k\partial_\lambda l(x^{k+1}, \lambda^{k+1}) + \lambda^{k+1},
\end{equation}
which, by the definition of $\mcT_l$, are equivalent to 
$$ (x^k + \rho_kv, \lambda^k) \in (\mcI + \rho_k\mcT_l)(x^{k+1},\lambda^{k+1}). $$
It follows from this and $\mcJ_{\rho_k}=(\mcI + \rho_k\mcT_l)^{-1}$ that  $(x^{k+1},\lambda^{k+1}) = \mcJ_{\rho_k}(x^k+\rho_kv,\lambda^k)$. By this and the non-expansion of $\mcJ_{\rho_k}$, we obtain
$$ \|(x^{k+1}, \lambda^{k+1}) - \mcJ_{\rho_k}(x^k,\lambda^k)\| = \|\mcJ_{\rho_k}(x^k + \rho_kv, \lambda^k) - \mcJ_{\rho_k}(x^k,\lambda^k)\| \leq \|\rho_kv\| \leq \rho_k\eta_k, $$
which yields \eqref{eq:mi-al=i-ppa} as desired. 
\end{proof}

\begin{proof}[Proof of Theorem \ref{prop:output-gantee-m}]
(i) Suppose that Algorithm~\ref{alg:mi-al} terminates in Step 3 at some iteration $k$. It then follows 
that $(x^+,\lambda^+)$  is already an $\epsilon$-KKT solution of problem \eqref{eq:conic-cp} 
or  the inequalities \eqref{eq:check-stop-m} hold for such $k$.  We next show that for the latter case, $(x^+, \lambda^+) = (x^{k+1},\lambda^{k+1})$ is also an $\epsilon$-KKT solution of~\eqref{eq:conic-cp}. To this end, suppose that \eqref{eq:check-stop-m} holds at the $k$th iteration. Notice that \eqref{eq:diff-x-lambda-m-v} holds for some $\|v\|\leq \eta_k$, which yields  
\[
\frac{1}{\rho_k}(x^k-x^{k+1}) + v \in \partial_x l(x^{k+1},\lambda^{k+1}), \quad \frac{1}{\rho_k}(\lambda^{k+1} - \lambda^k) \in \partial_\lambda l (x^{k+1},\lambda^{k+1}).
\]
By these, \eqref{eq:check-stop-m} and $(x^+, \lambda^+) = (x^{k+1},\lambda^{k+1})$, we obtain
\begin{align*}
\mbox{dist}(0,\partial_x l(x^+, \lambda^+)) & \leq \frac{1}{\rho_k}\|x^{k+1} - x^k - \rho_kv\| \leq \frac{1}{\rho_k}\|x^{k+1} - x^k\| + \|v\| \leq \epsilon,\\
\mbox{dist}(0,\partial_\lambda l(x^+, \lambda^+)) & \leq \frac{1}{\rho_k}\|\lambda^{k+1} - \lambda^k\| \leq \epsilon,
\end{align*}
which along with Definition \ref{defi:approx-KKT} imply that $(x^+,\lambda^+)$ is an $\epsilon$-KKT solution of problem \eqref{eq:conic-cp}.

(ii) Suppose for contradiction that Algorithm~\ref{alg:mi-al} does not terminate in a finite number of iterations. It then follows that  \eqref{eq:check-stop-m} does not hold for any $k$. By \eqref{eq:ippa-iter-cplx-min} and Lemma \ref{lemma:mi-al=i-ppa}, one has that
$$ \min_{k \leq i\leq 2k} \|(x^{i+1},\lambda^{i+1}) - (x^i,\lambda^i)\| \leq \frac{\sqrt{2}\left(D + 2\sum_{i=0}^{2k}\rho_i\eta_i\right)}{\sqrt{k+1}}, $$ 
where $D$ is defined in \eqref{param-m}. Since $\{\rho_k\}$ is assumed to be nondecreasing, we further have
\[
\min_{k \leq i\leq 2k} \frac{1}{\rho_i}\|(x^{i+1},\lambda^{i+1}) - (x^i,\lambda^i)\| \leq \frac{\sqrt{2}\left(D + 2\sum_{i=0}^{2k}\rho_i\eta_i\right)}{\rho_k\sqrt{k+1}}.
\]
By this and \eqref{rho-eta-m}, one has that $\min_{k \leq i\leq 2k} \|(x^{i+1},\lambda^{i+1}) - (x^i,\lambda^i)\|/\rho_i \to 0$ and $\eta_k\to 0$ as $k \to \infty$, which implies that \eqref{eq:check-stop-m} is satisfied for some $k$ and thus leads to a contradiction. 

(iii) Let $\hat x^*$ and $\hat\lambda^*$ be defined right above \eqref{param} and \eqref{param-m}, respectively. Suppose for contradiction that Algorithm~\ref{alg:mi-al} does not terminate within $N+1$ outer iterations. It then follows that \eqref{eq:check-stop-m} does not hold for all $0\le k \le N$. Then, by \eqref{param-m}, \eqref{eq:ippa-iter-cplx}, and \eqref{eq:mi-al=i-ppa}, we have that for all $0\le k \le N$,
\begin{equation*}\label{eq:mi-ppa-bd}
\|(x^{k+1},\lambda^{k+1}) - (x^k,\lambda^k)\| \leq \|(x^0,\lambda^0) - (\hat x^*, \hat\lambda^*)\| + \sum_{i=0}^k\rho_i\eta_i \leq D + \sum_{i=0}^k\rho_i\eta_i,
\end{equation*}
where $D$ is given in \eqref{param-m}. 
By this and \eqref{eq:cplx-out-general-m}, one can see that \eqref{eq:check-stop-m} is satisfied when $k = N$, which leads to a contradiction.  
\end{proof}

\begin{proof}
Since $0\in\mcT(z^*)$ and $\mcT$ is maximally monotone, it follows from \cite[Proposition 1]{Rock76a} that
\begin{equation}
\label{eq:suff-dec-ppa-1}
\| \mcJ_\rho(z) - z^*\|^2 + \|\mcJ_\rho(z) - z\|^2 \leq \|z - z^*\|^2,
\end{equation}
which implies that 
\begin{equation}
\label{eq:suff-dec-ppa-2}
\|\mcJ_\rho(z) - z^*\| \leq \|z - z^*\|, \quad \|\mcJ_\rho(z) - z\| \leq \|z - z^*\|, \quad \forall z \in \Re^n.
\end{equation}
	Let $\xi^k=z^{k+1} - \mcJ_{\rho_k}(z^k)$ for all $k\ge 0$. By this, \eqref{eq:suff-dec-ppa-2}, and \eqref{eq:iter-PPA} with $\rho = \rho_k$ and $z = z^k$, one has
	\[
	\|z^{k+1} - z^{*}\| \leq \|z^{k+1} - \mcJ_{\rho_k}(z^k)\| + \|\mcJ_{\rho_k}(z^k) - z^{*}\| 
	\leq \|\xi^k\| + \|z^k - z^{*}\|, \quad \forall k \ge 0.
	\]
	Summing up the above inequality from $k=t$ to $k=s-1$ yields 
	\beq \label{bdd-1}
	\|z^s - z^{*}\| \leq \|z^t - z^{*}\| + \sum_{i=t}^{s-1} \|\xi^i\|, \quad \forall s\geq t\geq 0.
	\eeq
	Notice from \eqref{eq:iter-PPA} that $\|\xi^k\| \le e_k$ for all $k\ge 0$, which along with \eqref{bdd-1} leads to \eqref{eq:iter-ppa-bd}. Besides, by~\eqref{eq:suff-dec-ppa-2} with $\rho=\rho_k$ and $z = z^k$, one has $ \|\mcJ_{\rho_k}(z^k) - z^k\|  \leq \|z^k - z^*\|$. These together with \eqref{eq:iter-PPA} and \eqref{eq:iter-ppa-bd} yield
	$$ \|z^{k+1} - z^k\| \leq \|z^{k+1} - \mcJ_{\rho_k}(z^k)\| + \|\mcJ_{\rho_k}(z^k) - z^k\| \leq e_k + \|z^k - z^*\| \leq \|z^0 - z^*\| + \sum_{i=0}^k e_i.  $$
	In addition, by the definition of $\xi^k$, and \eqref{eq:suff-dec-ppa-1} 
	with $\mcJ = \mcJ_{\rho_k}$ and $z = z^k$, one has
	\begin{equation*}
	\begin{split}
	\|\mcJ_{\rho_k}(z^k) - z^k\|^2 & \leq \|z^k - z^{*}\|^2 - \|\mcJ_{\rho_k}(z^k) - z^{*}\|^2 
	= \|z^k - z^{*}\|^2 - \|\mcJ_{\rho_k}(z^k) - z^{k+1} + z^{k+1} - z^{*}\|^2 \\
	& \leq \|z^k - z^{*}\|^2 - \|z^{k+1} - z^{*}\|^2 - \|\xi^k\|^2 + 2\|\xi^k\|\|z^{k+1} - z^{*}\|.
	\end{split}
	\end{equation*}
	Summing up the above inequality from $k = K$ to $k = 2K$ and using \eqref{bdd-1}, we obtain that 
	\begin{align}
	\sum_{k=K}^{2K}\|\mcJ_{\rho_k}(z^k) - z^k\|^2 & \leq \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\sum_{k=K}^{2K}\|\xi^k\|\left(\|z^K - z^{*}\| + \sum_{j=K}^k\|\xi^j\|\right) \nn\\
	& = \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + 2\sum_{k=K}^{2K}\sum_{j=K}^k\|\xi^k\|\|\xi^j\| \nn\\
	& = \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + \sum_{k=K}^{2K}\|\xi^k\|^2 + \left(\sum_{k=K}^{2K}\|\xi^k\|\right)^2 \nn\\
	& = \|z^K - z^{*}\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + \left(\sum_{k=K}^{2K}\|\xi^k\|\right)^2 \nn\\
	& = \left( \|z^K - z^{*}\| + \sum_{k=K}^{2K}\|\xi^k\| \right)^2 \leq \left( \|z^0 - z^{*}\| + \sum_{k=0}^{2K}\|\xi^k\| \right)^2, \label{eq:bound-sum-jz-z}
	\end{align}
	where \eqref{eq:bound-sum-jz-z} follows from \eqref{bdd-1} with $t=0$ and $s = K$. Again, by the definition of $\xi^k$, one has
	$$ \|z^{k+1} - z^k\|^2 = \|\mcJ_{\rho_k}(z^k) + \xi^k- z^k \|^2 \leq 2\left(\|\mcJ_{\rho_k}(z^k) - z^k\|^2 + \|\xi^k\|^2\right). $$
	This together with~\eqref{eq:bound-sum-jz-z} yields
	\begin{align*}
	\sum_{k = K}^{2K}\|z^{k+1} - z^k\|^2 & \leq 2\sum_{k = K}^{2K}\|\mcJ_{\rho_k}(z^k) - z^k\|^2 + 2\sum_{k = K}^{2K}\|\xi^k\|^2 
	 \leq 2\left( \|z^0 - z^{*}\| + \sum_{k=0}^{2K}\|\xi^k\| \right)^2 + 2\sum_{k=0}^{2K}\|\xi^k\|^2 \\
	& \leq 2\left( \|z^0 - z^{*}\| + 2\sum_{k=0}^{2K}\|\xi^k\| \right)^2,
	\end{align*}
	which along with $\|\xi^k\| \le e_k$ leads to \eqref{eq:ippa-iter-cplx-min}. The proof is then completed.
\end{proof}

