\| \mcJ_\rho(z) - z^*\|^2 + \|\mcJ_\rho(z) - z\|^2 \leq \|z - z^*\|^2,
\end{equation}
which implies that 
\begin{equation}
\label{eq:suff-dec-ppa-2}
\|\mcJ_\rho(z) - z^*\| \leq \|z - z^*\|, \quad \|\mcJ_\rho(z) - z\| \leq \|z - z^*\|, \quad \forall z \in \Re^n.
